fn all_characters_same(s: &[u8]) -> bool {
    // An empty array or a single-element array is considered to have all identical characters
    if s.len() <= 1 {
        return true;
    }

    // Get the first character to compare with the rest
    let first_char = s[0];

    // Check if all characters are the same as the first character
    for &byte in s.iter() {
        if byte != first_char {
            return false;
        }
    }

    true
}